package com.samsung.android.app;

/**
 * Stand-in (generated by .github/scripts/samsung-standins, then made a Service by hand): One UI's base for services
 * that show their own window (Finder's DeX window). Off One UI there is no DeX, so it only has to be a Service with the
 * members Finder uses, answering "absent" (no Samsung code).
 */
public class SemUiSupportService extends android.app.Service {
    public SemUiSupportService() {
    }
    @Override
    public android.os.IBinder onBind(android.content.Intent p0) {
        return null;
    }
    public android.view.WindowManager.LayoutParams createLayoutParams() {
        return new android.view.WindowManager.LayoutParams(android.view.WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY);
    }
    public boolean dispatchKeyEvent(android.view.KeyEvent p0) {
        return false;
    }
    public boolean dispatchTouchEvent(android.view.MotionEvent p0) {
        return false;
    }
    public android.content.Context getContext() {
        return this;
    }
    public android.view.Window getWindow() {
        return null;
    }
    public void onAttachedToWindow() {
    }
    public void onDetachedFromWindow() {
    }
    public void stopUiSupportService() {
        stopSelf();
    }
}
